package com.landportal.entity;
import jakarta.persistence.*;
@Entity @Table(name="officer_profiles") public class OfficerProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne(optional=false) @JoinColumn(name="user_id",unique=true) User user; @Column(nullable=false,unique=true) String employeeId; String department,designation,district,officeName; boolean active=true; public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getEmployeeId(){return employeeId;} public void setEmployeeId(String v){employeeId=v;} public String getDepartment(){return department;} public void setDepartment(String v){department=v;} public String getDesignation(){return designation;} public void setDesignation(String v){designation=v;} public String getDistrict(){return district;} public void setDistrict(String v){district=v;} public String getOfficeName(){return officeName;} public void setOfficeName(String v){officeName=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} }
